from pathlib import Path
from collections import Counter

for p in sorted(Path("/workspace/logs/awm_runtime").glob("*.log")):
    print("===", p.name)
    levels = Counter()
    errors = []
    with p.open(errors="replace") as f:
        for i, line in enumerate(f):
            if " | ERROR " in line or " | CRITICAL " in line or "Traceback" in line or "Exception" in line or "judge_error" in line or "verifier" in line.lower():
                errors.append((i, line.strip()[:200]))
            if " | " in line:
                parts = line.split(" | ")
                if len(parts) >= 2:
                    levels[parts[1].strip()] += 1
    print("Levels:", levels)
    print("Matched lines:", len(errors))
    for idx, l in errors[:30]:
        print(f"  L{idx}: {l}")
'

